function digitSumAbs(n){ var s=0; n=Math.abs(Math.floor(n)); while(n>0){ s+=n%10; n=Math.floor(n/10);} return s; }
function isHarshad(n){
  n=Math.floor(Math.abs(+n));
  if(isNaN(n)||n<1) return {error:'请输入正整数'};
  var ds=digitSumAbs(n);
  if(ds===0) return {error:'无效数字'};
  return {value:n, isHarshad:(n%ds===0), digitSum:ds, quotient:n/ds};
}
var EXPORTS={isHarshad:isHarshad};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.HarshadForgePure = EXPORTS; }
